import{_ as t,o,c as a,a2 as i}from"./chunks/framework.D_ZOUi6P.js";const p=JSON.parse('{"title":"ADR 002 - Declarative telemetry routing with experimental.pipeline_config","description":"","frontmatter":{"date":"2026-10-01T00:00:00.000Z","title":"ADR 002 - Declarative telemetry routing with `experimental.pipeline_config`"},"headers":[],"relativePath":"reference/adrs/records/002-declarative-telemetry-routing.md","filePath":"reference/adrs/records/002-declarative-telemetry-routing.md","lastUpdated":1793273055000}'),n={name:"reference/adrs/records/002-declarative-telemetry-routing.md"};function r(s,e,l,d,c,h){return o(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="adr-002-declarative-telemetry-routing" tabindex="-1">ADR 002 - Declarative telemetry routing <a class="header-anchor" href="#adr-002-declarative-telemetry-routing" aria-label="Permalink to &quot;ADR 002 - Declarative telemetry routing&quot;">​</a></h1><h2 id="problem-statement" tabindex="-1">Problem statement <a class="header-anchor" href="#problem-statement" aria-label="Permalink to &quot;Problem statement&quot;">​</a></h2><p>ADP sends every metric to the primary endpoint and to every entry in <code>additional_endpoints</code>. Operators increasingly need to send different subsets of their metrics to different places: a second organization on another site, a separate organization for one team&#39;s workloads, or an endpoint that only needs a narrow slice of the stream.</p><p>Between the various routing mechanisms (primary site/URL, additional endpoints, MRF, Cluster Agent Local Autoscaling) and filtering mechanisms (DSD-specific blocklists, Agent-Side Tag Filtering, Metrics Endpoint Routing), we lack a cohesive way to both define the complete set of target organizations/endpoints where telemetry data should be routed, as well as the means by which deciding which subsets of the overall telemetry data flow should go to those targets.</p><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><h3 id="what-exists-today" tabindex="-1">What exists today <a class="header-anchor" href="#what-exists-today" aria-label="Permalink to &quot;What exists today&quot;">​</a></h3><p>For high-level routing, we have the following:</p><ul><li><strong>Dual shipping</strong> through <code>additional_endpoints</code> is all-or-nothing: every additional endpoint receives every metric.</li><li><strong><code>experimental.metrics_endpoint_routing</code></strong> (#2618, #2690) adds per-endpoint allowlists of exact metric names and literal prefixes. An endpoint with an allowlist leaves the ordinary stream and receives only its allowlist, through its own filter and encoder.</li></ul><p><code>experimental.metrics_endpoint_routing</code> proved out the idea, but its shape limits how far it can go: allowlists can&#39;t be shared between endpoints, it&#39;s keyed by URL and so per-API key routing is not possible, and it only operates on endpoints that already exist in <code>dd_url</code>/<code>site</code> or <code>additional_endpoints</code>, and those endpoints then receive every other signal too.</p><p>Beyond that, there&#39;s various mechanisms for filtering the actual telemetry data itself (<code>statsd_metrics_blocklist</code>, ASTA) which apply to all endpoints, but exist as mechanisms adjacent to Metrics Endpoint Routing, and all of these affect the pipeline at different points.</p><h3 id="constraints" tabindex="-1">Constraints <a class="header-anchor" href="#constraints" aria-label="Permalink to &quot;Constraints&quot;">​</a></h3><ul><li><strong>Correctness comes first.</strong> An endpoint must receive each metric at most once, and a configuration mistake must not silently drop metrics or send them somewhere they weren&#39;t meant to go.</li><li><strong>No cost when unused.</strong> The metrics path is hot, and most deployments never need to configure advanced routing.</li><li><strong>Encoding is expensive.</strong> Encoding the same stream once per endpoint doesn&#39;t scale with the number of endpoints.</li><li><strong>Delivery identity matters beyond routing.</strong> Retry queues, including transactions persisted to disk, belong to an endpoint and must survive API key rotation.</li><li><strong>Existing features keep working</strong>: Multi-Region Failover, autoscaling failover forwarding, alternate metrics intakes, and V2/V3 protocol selection.</li></ul><h2 id="considered-options" tabindex="-1">Considered options <a class="header-anchor" href="#considered-options" aria-label="Permalink to &quot;Considered options&quot;">​</a></h2><ul><li><strong>Extend <code>experimental.metrics_endpoint_routing</code></strong>: add tag allowlists and further per-endpoint settings to the existing keys.</li><li><strong>General-purpose topology configuration</strong>: let operators define arbitrary sources, transforms, and sinks, in the style of Vector.</li><li><strong>Declarative routing compiled into a routing plan</strong>: name sets of telemetry (<strong>filter sets</strong>), name places it can go (<strong>destinations</strong>), and connect them with <strong>routes</strong>; compile the result at startup into a plan that ADP builds its topology from.</li></ul><h2 id="decision-outcome" tabindex="-1">Decision outcome <a class="header-anchor" href="#decision-outcome" aria-label="Permalink to &quot;Decision outcome&quot;">​</a></h2><p>Chosen option: <strong>Declarative routing compiled into a routing plan</strong></p><p>Extending the endpoint allowlists keeps the endpoint-centric shape and the URL-keyed identity, which are the root of their limits. A general-purpose topology configuration exposes far more surface than operators need, makes it easy to build topologies that are wrong in ways we can&#39;t detect, and couples user configuration to ADP&#39;s internal component graph.</p><p>Declarative routing separates <em>what</em> telemetry is (filter sets), <em>where</em> it can go (destinations), and <em>policy</em> (routes). Because ADP compiles it into a plan rather than interpreting it, ADP can validate the whole configuration up front, share work between endpoints that receive the same metrics, and fall back to the ordinary topology when the configuration routes like the ordinary setup does.</p><p>Most importantly, however, is that this option can be implemented by the Core Agent to allow for controlling the routing of all telemetry data types by using a unified configuration approach that all relevant processes interpret based on their own needs. For example, the Core Agent could parse this routing configuration to support advanced routing of <em>logs</em> while ADP parses it to handle just <em>metrics</em>, both processes reading the same configuration but acting on it in only the ways that are relevant to them.</p><p>The initial scope is deliberately narrow: metrics only, read at startup, under <code>experimental</code>. See the <a href="./../../../agent-data-plane/configuration/declarative-routing">user documentation</a> for the full configuration surface.</p><h3 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h3><ul><li>Good, because deployments that don&#39;t configure routing, or configure it trivially, run the same topology as before.</li><li>Good, because encoding cost scales with distinct filters rather than with endpoints.</li><li>Good, because delivery guarantees hold by construction: at most once per target, independent of route order, and validated before ADP starts.</li><li>Good, because multiple organizations at one URL, and alternate intakes, are a first-class concept.</li><li>Good, because the configuration and the matchers aren&#39;t specific to metrics, so other signals can adopt them without changing the configuration&#39;s shape.</li><li>Good, because the compiler is a pure function from configuration to plan, which keeps it unit-testable; Panoramic correctness tests cover the end-to-end behavior.</li><li>Bad, because changing the configuration requires a restart.</li><li>Bad, because the router adds a hop and a per-context decision cache to the metrics path, and each additional branch a metric matches copies it.</li><li>Bad, because each declared target has its own retry queue, which adds memory and disk use per declared API key.</li><li>Bad, because a plan can&#39;t exceed 64 filtered branches.</li><li>Bad, because two routing configurations coexist until <code>experimental.metrics_endpoint_routing</code> is removed.</li><li>Bad, because the compiler and predicate canonicalization are a meaningful amount of code to maintain.</li></ul><h2 id="open-questions" tabindex="-1">Open questions <a class="header-anchor" href="#open-questions" aria-label="Permalink to &quot;Open questions&quot;">​</a></h2><ul><li>How would we graduate this out of experimental status?</li><li>Is there enough value in this to expose it as a first-class citizen on the Datadog UI?</li><li>Would / could this cannibalize Observability Pipelines?</li><li>Are there any gotchas around API key updates that we can&#39;t handle with our existing approach in the current encoder/forwarder code?</li><li>Is the configuration shape as defined <em>actually</em> sufficient enough to eventually support logs and traces (and other signals)?</li></ul><h2 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h2><ul><li><a href="./../../../agent-data-plane/configuration/declarative-routing">Declarative metrics routing</a> (user documentation)</li></ul>',26)])])}const g=t(n,[["render",r]]);export{p as __pageData,g as default};
